      return this.normalizedGroup(a.roundGroup).localeCompare(this.normalizedGroup(b.roundGroup));
    }
    boardSort(m) {
      const n = Number(m.boardNumber);
      return Number.isFinite(n) ? n : 999;
    }
    latestFinalizedSrrRound(matches) {
      const rounds = [...new Set(matches.filter(m => (m.roundType || 'SRR').toUpperCase() === 'SRR' && !!m.scoreFinalized).map(m => m.roundNumber || 0))];
      return rounds.length ? Math.max(...rounds) : 0;
    }
    matchRoundLabel(m) {
      return (m.roundType || 'SRR').toUpperCase() === 'SRR' ? `SRR Round #${m.roundNumber}` : this.stageDisplay(m.roundType || '');
    }
    roundGroupLabel(m) {
      const g = this.normalizedGroup(m.roundGroup);
      return g === 'Main' ? '' : `${g} -`;
    }
    stageDisplay(stage) {
      const s = (stage || '').toUpperCase();
      if (s === 'PRE_QUARTERS') return 'Pre-Quarter Finals';
      if (s === 'QUARTERS') return 'Quarter Finals';
      if (s === 'SEMIFINALS') return 'Semi Finals';
      if (s === 'FINALS') return 'Finals';
      return stage || 'Round';
