    winnerName(m) {
      if (m.winnerId === m.player1Id) return m.player1Name || '';
      if (m.winnerId === m.player2Id) return m.player2Name || '';
      return '';
    }
    loserName(m) {
      if (m.winnerId === m.player1Id) return m.player2Name || '';
      if (m.winnerId === m.player2Id) return m.player1Name || '';
      return '';
    }
    winnerRank(m) {
      if (m.winnerId === m.player1Id) return m.player1Rank;
      if (m.winnerId === m.player2Id) return m.player2Rank;
      return undefined;
    }
    loserRank(m) {
      if (m.winnerId === m.player1Id) return m.player2Rank;
      if (m.winnerId === m.player2Id) return m.player1Rank;
      return undefined;
    }
    winnerScore(m) {
      return m.winnerId === m.player1Id ? m.player1Score || 0 : m.player2Score || 0;
    }
    loserScore(m) {
      return m.winnerId === m.player1Id ? m.player2Score || 0 : m.player1Score || 0;
    }
    qfAll(group) {
      return this.padMatches(group.quarters, 4, 'QF');
    }
    sfAll(group) {
      return this.padMatches(group.semis, 2, 'SF');
    }
    finalMatches(group) {
      return this.padMatches(group.finals, 1, 'FINAL');
    }
    championName(group) {
      const final = group.finals && group.finals.length ? group.finals[0] : undefined;
      return final && this.winnerName(final) ? this.winnerName(final) : 'TBD';
    }
    currentKnockoutMessage(group) {
      if (group.finals && group.finals.some(m => m.scoreFinalized)) return 'Final results are available.';
